import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

_src = r'''
#include <torch/extension.h>
#include <ATen/cuda/CUDAContext.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAGuard.h>

#ifndef WARP_SIZE
#define WARP_SIZE 32
#endif

__inline__ __device__ float warp_sum(float v) {
    unsigned mask = 0xffffffffu;
    #pragma unroll
    for (int offset = 16; offset > 0; offset >>= 1) {
        v += __shfl_down_sync(mask, v, offset);
    }
    return v;
}

__inline__ __device__ float block_sum(float v) {
    __shared__ float shared[32];
    int lane = threadIdx.x & 31;
    int wid = threadIdx.x >> 5;
    v = warp_sum(v);
    if (lane == 0) shared[wid] = v;
    __syncthreads();
    v = (threadIdx.x < (blockDim.x + 31) / 32) ? shared[lane] : 0.0f;
    if (wid == 0) v = warp_sum(v);
    return v;
}

template <typename scalar_t, int BLOCK>
__global__ __launch_bounds__(BLOCK, 2)
void layernorm_kernel(const scalar_t* __restrict__ x,
                      const scalar_t* __restrict__ w,
                      const scalar_t* __restrict__ b,
                      scalar_t* __restrict__ y,
                      long stride, int N, float eps) {
    int row = blockIdx.x;
    const scalar_t* __restrict__ xrow = x + (long)row * stride;
    scalar_t* __restrict__ yrow = y + (long)row * stride;

    float sum = 0.0f;
    for (int col = threadIdx.x; col < N; col += BLOCK) {
        sum += static_cast<float>(xrow[col]);
    }
    sum = block_sum(sum);
    __shared__ float smem[2];
    if (threadIdx.x == 0) smem[0] = sum / (float)N;
    __syncthreads();
    float mean = smem[0];

    float var_sum = 0.0f;
    for (int col = threadIdx.x; col < N; col += BLOCK) {
        float xv = static_cast<float>(xrow[col]) - mean;
        var_sum += xv * xv;
    }
    var_sum = block_sum(var_sum);
    if (threadIdx.x == 0) smem[1] = rsqrtf(var_sum / (float)N + eps);
    __syncthreads();
    float rstd = smem[1];

    for (int col = threadIdx.x; col < N; col += BLOCK) {
        float xv = static_cast<float>(xrow[col]);
        float wv = static_cast<float>(w[col]);
        float bv = static_cast<float>(b[col]);
        float out = (xv - mean) * rstd * wv + bv;
        yrow[col] = static_cast<scalar_t>(out);
    }
}

template <typename scalar_t>
void launch_typed(const torch::Tensor& x, const torch::Tensor& w, const torch::Tensor& b,
                  torch::Tensor& y, int64_t rows, int64_t N, int64_t stride) {
    cudaStream_t stream = at::cuda::getCurrentCUDAStream();
    dim3 grid((unsigned)rows);
    const scalar_t* xp = x.data_ptr<scalar_t>();
    const scalar_t* wp = w.data_ptr<scalar_t>();
    const scalar_t* bp = b.data_ptr<scalar_t>();
    scalar_t* yp = y.data_ptr<scalar_t>();
    if (N <= 64) {
        layernorm_kernel<scalar_t, 64><<<grid, 64, 0, stream>>>(xp, wp, bp, yp, (long)stride, (int)N, 1.0e-5f);
    } else if (N <= 256) {
        layernorm_kernel<scalar_t, 128><<<grid, 128, 0, stream>>>(xp, wp, bp, yp, (long)stride, (int)N, 1.0e-5f);
    } else if (N <= 1024) {
        layernorm_kernel<scalar_t, 256><<<grid, 256, 0, stream>>>(xp, wp, bp, yp, (long)stride, (int)N, 1.0e-5f);
    } else {
        layernorm_kernel<scalar_t, 256><<<grid, 256, 0, stream>>>(xp, wp, bp, yp, (long)stride, (int)N, 1.0e-5f);
    }
}

torch::Tensor layernorm_forward(torch::Tensor x, torch::Tensor w, torch::Tensor b) {
    c10::cuda::CUDAGuard device_guard(x.device());
    auto y = torch::empty_like(x);
    int64_t rows = x.size(0);
    int64_t N = x.size(1);
    int64_t stride = x.stride(0);
    AT_DISPATCH_FLOATING_TYPES_AND2(at::ScalarType::Half, at::ScalarType::BFloat16, x.scalar_type(), "layernorm_forward", [&] {
        launch_typed<scalar_t>(x, w, b, y, rows, N, stride);
    });
    return y;
}

PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {
    m.def("layernorm_forward", &layernorm_forward, "LayerNorm forward CUDA");
}
